function show(id){views.forEach(v=>$("#"+v).classList.toggle("hidden",v!==id));}
async function api(url,options={}){const r=await fetch(url,{credentials:"same-origin",headers:{"Content-Type":"application/json",...(options.headers||{})},...options});const data=r.status===204?{}:await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||"حدث خطأ غير متوقع");return data;}
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function avatar(src,name){return src?'<img src="'+src+'" alt="">':(name||"?").trim().slice(0,2).toUpperCase();}
function escapeHtml(s){return String(s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function notify(message,error=false){let el=$("#dashboard-toast");if(!el){el=node("div","dashboard-toast");el.id="dashboard-toast";document.body.appendChild(el);}el.textContent=message;el.classList.toggle("error",error);el.classList.add("visible");clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove("visible"),3500);}
async function init(){loadPublicShowcase();try{const data=await api("/dashboard/api/me");if(!data.authenticated){show("login-view");return;}isDeveloper=!!data.developer;$("#user-chip").textContent=(data.user.globalName||data.user.username)+(isDeveloper?" • مطوّر":"");$("#user-chip").classList.remove("hidden");const developerCard=$("[data-mode='developer']");if(developerCard)developerCard.classList.toggle("hidden",!isDeveloper);const makerCard=$("[data-mode='maker']");if(makerCard)makerCard.classList.toggle("hidden",!isDeveloper);const premiumCard=$("[data-mode='premium']");if(premiumCard)premiumCard.classList.toggle("hidden",!data.premiumAvailable);show("chooser");}catch(e){show("login-view");}}
document.querySelectorAll("[data-mode]").forEach(btn=>btn.addEventListener("click",()=>btn.dataset.mode==="maker"?openMakerWorkspace():btn.dataset.mode==="support"?openSupportWorkspace():chooseMode(btn.dataset.mode)));
