async function renderUserSupport(){const root=$("#support-page-content");root.replaceChildren();const panel=node("div","dashboard-panel"),title=node("h3","","إنشاء تذكرة جديدة"),grid=node("div","settings-grid");panel.append(title);const cat=node("select","field-control");[["complaint","شكوى"],["premium","دعم Premium"],["purchase","طلب شراء"],["suggestion","اقتراح"]].forEach(([v,l])=>cat.append(new Option(l,v)));const titleInput=node("input","field-control");titleInput.placeholder="عنوان التذكرة";const bodyInput=node("textarea","field-control");bodyInput.rows=4;bodyInput.placeholder="اشرح طلبك أو المشكلة بالتفصيل...";grid.append(cat,titleInput,bodyInput);panel.append(grid);const create=node("button","primary-action","إرسال التذكرة");create.addEventListener("click",async()=>{create.disabled=true;try{await api("/dashboard/api/support",{method:"POST",body:JSON.stringify({category:cat.value,title:titleInput.value,body:bodyInput.value})});notify("تم إنشاء التذكرة.");await renderUserSupport();}catch(e){notify(e.message,true);}finally{create.disabled=false;}});panel.append(create);root.append(panel);const list=node("div","dashboard-panel");list.append(node("h3","","تذاكري"));root.append(list);try{const data=await api("/dashboard/api/support");(data.tickets||[]).forEach(t=>{const card=node("div","maker-item"),head=node("div","maker-item-head");head.append(node("b","", "#"+t.ticketNo+" • "+t.title),node("span","maker-status",t.status==="open"?"مفتوحة":"مغلقة"));card.append(head,node("p","", "النوع: "+({complaint:"شكوى",premium:"دعم Premium",purchase:"طلب شراء",suggestion:"اقتراح"}[t.category]||t.category)+" • آخر تحديث: "+new Date(t.updatedAt).toLocaleString("ar-SA")));(t.messages||[]).forEach(m=>{const msg=node("p","",m.username+": "+m.body);card.append(msg);});if(t.status==="open"){const reply=node("textarea","field-control");reply.rows=2;reply.placeholder="اكتب ردك...";const send=node("button","ghost-button","إرسال الرد");send.addEventListener("click",async()=>{try{await api("/dashboard/api/support/"+t.ticketNo+"/replies",{method:"POST",body:JSON.stringify({body:reply.value})});notify("تم إرسال الرد.");await renderUserSupport();}catch(e){notify(e.message,true);}});card.append(reply,send);}list.append(card);});if(!(data.tickets||[]).length)list.append(node("p","","لم تنشئ أي تذاكر بعد."));}catch(e){list.append(node("p","showcase-empty",e.message));}}
