function renderLogs(root){const panel=node("div","dashboard-panel");panel.append(node("h3","","سجل تغييرات الداشبورد"));const audit=workspaceData.logs?.audit||[];if(!audit.length)panel.append(node("p","","لا توجد تغييرات مسجلة حتى الآن."));audit.forEach(item=>{const row=node("div","log-row");const date=new Date(item.at).toLocaleString("ar-SA");row.append(node("b","",item.section),node("span","",item.username+" • "+date),node("small","",(item.changes||[]).join("، ")));panel.append(row);});root.append(panel);const discord=node("div","dashboard-panel");discord.append(node("h3","","آخر رسائل روم اللوق"));discord.append(node("p","","القناة: "+(workspaceData.logs?.channelId||"غير محددة")));const messages=workspaceData.logs?.messages||[];if(!messages.length)discord.append(node("p","","لا توجد رسائل متاحة أو لم يتم تحديد روم اللوق."));messages.forEach(m=>{const row=node("div","log-row");row.append(node("b","",m.author),node("span","",new Date(m.at).toLocaleString("ar-SA")),node("small","",m.content));discord.append(row);});root.append(discord);}
